from flask import Flask, request, redirect, url_for, session, render_template_string
import os
import json

app = Flask(__name__)
app.secret_key = os.urandom(24)

USER_DATA_DIR = '/var/lib/myapp/userdata'

TEMPLATE = '''
<html>
<body>
<h2>Account Settings</h2>
<form method="POST" action="/update-profile">
  <label>Display Name:</label>
  <input type="text" name="display_name" value="{{ user.display_name }}">
  <label>Email:</label>
  <input type="email" name="email" value="{{ user.email }}">
  <label>Bio:</label>
  <textarea name="bio">{{ user.bio }}</textarea>
  <label>Avatar URL:</label>
  <input type="text" name="avatar_url" value="{{ user.avatar_url }}">
  <label>Export Path (for data export):</label>
  <input type="text" name="export_path" value="{{ user.export_path }}">
  <button type="submit">Save Changes</button>
</form>
<form method="POST" action="/export-data">
  <button type="submit">Export My Data</button>
</form>
</body>
</html>
'''

def get_user_profile(username):
    filepath = os.path.join(USER_DATA_DIR, f"{username}.json")
    if os.path.exists(filepath):
        with open(filepath, 'r') as f:
            return json.load(f)
    return {"display_name": "", "email": "", "bio": "", "avatar_url": "", "export_path": f"/var/lib/myapp/exports/{username}"}

def save_user_profile(username, data):
    filepath = os.path.join(USER_DATA_DIR, f"{username}.json")
    with open(filepath, 'w') as f:
        json.dump(data, f)

@app.route('/profile')
def profile():
    if 'username' not in session:
        return redirect('/login')
    user = get_user_profile(session['username'])
    return render_template_string(TEMPLATE, user=user)

@app.route('/update-profile', methods=['POST'])
def update_profile():
    if 'username' not in session:
        return redirect('/login')
    # No CSRF token validation
    username = session['username']
    profile = get_user_profile(username)
    profile['display_name'] = request.form.get('display_name', '')
    profile['email'] = request.form.get('email', '')
    profile['bio'] = request.form.get('bio', '')
    profile['avatar_url'] = request.form.get('avatar_url', '')
    profile['export_path'] = request.form.get('export_path', '')
    save_user_profile(username, profile)
    return redirect('/profile')

@app.route('/export-data', methods=['POST'])
def export_data():
    if 'username' not in session:
        return redirect('/login')
    username = session['username']
    profile = get_user_profile(username)
    export_path = profile.get('export_path', f'/var/lib/myapp/exports/{username}')
    # Write user data export to the configured path
    os.makedirs(os.path.dirname(export_path), exist_ok=True)
    with open(export_path, 'w') as f:
        json.dump({
            "username": username,
            "profile": profile,
            "exported": True
        }, f)
    return f"Data exported to {export_path}"

@app.route('/login', methods=['GET', 'POST'])
def login():
    if request.method == 'POST':
        session['username'] = request.form.get('username', 'guest')
        return redirect('/profile')
    return '<form method="POST"><input name="username"><button>Login</button></form>'

if __name__ == '__main__':
    os.makedirs(USER_DATA_DIR, exist_ok=True)
    app.run(host='0.0.0.0', port=5000)
